const SVG_NS = 'http://www.w3.org/2000/svg';
export const ICON_NAMES = Object.freeze(Object.keys(PATHS));

function normalise(name) {
  let n = String(name).replace(/^Icons\./, '');
  if (PATHS[n]) return n;
  const r = n.replace(/^Rounded\./, 'Filled.').replace(/^Default\./, 'Filled.');
  if (PATHS[r]) return r;
  return n;
}

export function iconPaths(name) { return PATHS[normalise(name)] || null; }

function svgRoot(size, viewBox, opts) {
  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('viewBox', viewBox);
  svg.setAttribute('width', '24');
  svg.setAttribute('height', '24');
  svg.style.width = size;
  svg.style.height = size;
  svg.style.flex = 'none';
  svg.style.display = 'block';
  svg.style.color = opts.tint || '';
  svg.setAttribute('fill', 'currentColor');
  svg.setAttribute('class', 'icon' + (opts.class ? ' ' + opts.class : ''));
  if (opts.style) Object.assign(svg.style, opts.style);
  if (opts.contentDescription) {
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', opts.contentDescription);
  } else svg.setAttribute('aria-hidden', 'true');
  return svg;
}

export function icon(name, size = 'var(--size-standardIcon)', opts = {}) {
  const key = normalise(name);
  const paths = PATHS[key];
  const svg = svgRoot(size, '0 0 24 24', opts);
  svg.dataset.icon = key;
  if (!paths) { console.warn('icons.js: unknown icon', name); return svg; }
  for (const p of paths) {
    const el = document.createElementNS(SVG_NS, 'path');
    el.setAttribute('d', p.d);
    if (p.fillOpacity != null) el.setAttribute('fill-opacity', String(p.fillOpacity));
    if (p.fillRule) el.setAttribute('fill-rule', p.fillRule);
    svg.appendChild(el);
  }
  return svg;
}

